describe('User Account Deletion', () => {
    beforeEach(() => {
        cy.visit('/login');
        cy.get('input[name="username"]').type('testuser');
        cy.get('input[name="password"]').type('password123');
        cy.get('button[type="submit"]').click();
        cy.visit('/profile');
    });

    it('should delete the account after confirming with the password (happy path)', () => {
        cy.get('button.delete-account').click();
        cy.get('input[name="confirm-password"]').type('password123');
        cy.get('button.confirm-delete').click();
        cy.get('.notification').should('contain', 'Your account has been deleted successfully.');
        cy.url().should('eq', Cypress.config().baseUrl + '/login');
    });

    it('should show an error message if the password is incorrect (edge case)', () => {
        cy.get('button.delete-account').click();
        cy.get('input[name="confirm-password"]').type('wrongpassword');
        cy.get('button.confirm-delete').click();
        cy.get('.error-message').should('contain', 'Incorrect password. Please try again.');
    });
});
